package com.hotel.dao.impl;
import com.hotel.dao.RoomDao; import com.hotel.dto.AvailableRoomDto; import com.hotel.exception.DataAccessException; import com.hotel.util.DBConnection; import java.sql.*; import java.util.*;
public class RoomDaoImpl implements RoomDao { public Optional<List<AvailableRoomDto>> findAvailable(long id,Integer floor){String target="SELECT rr.room_type_id,rr.adult_count,rr.child_count,v.check_in_date,v.check_out_date FROM reservation_rooms rr JOIN reservations v ON v.reservation_id=rr.reservation_id WHERE rr.reservation_room_id=?";String q="SELECT rm.room_id,rm.room_number,rm.floor_number,rt.type_code,rt.type_name,rt.bed_type,rt.max_adults,rt.max_children,rm.operational_status,rm.cleaning_status FROM rooms rm JOIN room_types rt ON rt.room_type_id=rm.room_type_id WHERE rm.is_active=1 AND rt.is_active=1 AND rm.operational_status='AVAILABLE' AND rm.cleaning_status IN ('CLEAN','INSPECTED') AND rm.room_type_id=? AND rt.max_adults>=? AND rt.max_children>=? AND (? IS NULL OR rm.floor_number=?) AND NOT EXISTS(SELECT 1 FROM room_assignments ra JOIN reservation_rooms xrr ON xrr.reservation_room_id=ra.reservation_room_id JOIN reservations xv ON xv.reservation_id=xrr.reservation_id WHERE ra.room_id=rm.room_id AND ra.is_current=1 AND xv.status_code NOT IN ('CANCELLED','NO_SHOW','CHECKED_OUT') AND xv.check_in_date<? AND xv.check_out_date>?) ORDER BY rm.floor_number ASC,rm.room_number ASC";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(target)){p.setLong(1,id);long type;int adults,children;java.time.LocalDate in,out;try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();type=r.getLong(1);adults=r.getInt(2);children=r.getInt(3);in=r.getObject(4,java.time.LocalDate.class);out=r.getObject(5,java.time.LocalDate.class);}List<AvailableRoomDto>a=new ArrayList<>();try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,type);s.setInt(2,adults);s.setInt(3,children);if(floor==null){s.setNull(4,Types.INTEGER);s.setNull(5,Types.INTEGER);}else{s.setInt(4,floor);s.setInt(5,floor);}s.setDate(6,java.sql.Date.valueOf(out));s.setDate(7,java.sql.Date.valueOf(in));try(ResultSet r=s.executeQuery()){while(r.next())a.add(new AvailableRoomDto(r.getLong(1),r.getString(2),(Integer)r.getObject(3),r.getString(4),r.getString(5),r.getString(6),r.getInt(7),r.getInt(8),r.getString(9),r.getString(10),in,out));}}return Optional.of(a);}catch(SQLException e){throw new DataAccessException("Unable to find available rooms",e);}} }
